stylesheet:
html,
body {
	background: #171b1d;
}

body {
	color: #ccc;
	font-family: Arial, Helvetica, sans-serif;
	font-size: 13px;
}

a:link,
a:visited {
	color: #4dabb7;
}

a:hover,
a:active {
	color: #fff;
	text-decoration: none;
}

#container {
	min-width: 0;
	color: #ccc;
	font-family: inherit;
}

.wrapper {
	box-sizing: border-box;
	width: calc(100% - 32px);
	min-width: 0;
	max-width: 1180px;
}

#logo {
	min-height: 150px;
	padding: 20px 0;
	background: #151515;
	border-bottom: 1px solid #262626;
	display: flex;
	align-items: center;
}

#logo .wrapper {
	display: flex;
	align-items: center;
	justify-content: space-between;
	gap: 32px;
}

#logo img {
	display: block;
	max-width: 420px;
	width: auto;
	height: auto;
}

#logo ul.top_links {
	margin: 0;
	display: flex;
	flex-wrap: wrap;
	justify-content: flex-end;
	gap: 6px;
	max-width: 640px;
}

#header ul.menu li {
	margin: 0;
	display: block;
}

#header ul.menu li a {
	padding: 8px 10px 8px 30px;
	border-radius: 3px;
	color: #fff;
}

#header ul.menu li a:hover {
	background-color: #262626;
}

#panel .upper {
	background: #0e0e0e;
	border-color: #262626 #101010;
}

#panel .lower {
	background: #181818;
	color: #969696;
	border-color: #262626;
}

#panel .lower a:link,
#panel .lower a:visited,
#panel .lower a:hover,
#panel .lower a:active {
	color: #ccc;
}

#content {
	box-sizing: border-box;
	padding: 18px 0 28px;
	background: transparent;
}

.tborder {
	background: #181818;
	border: 1px solid #101010;
	border-radius: 3px;
	box-shadow: inset 0 0 1px 1px #262626, 0 8px 24px rgba(0, 0, 0, 0.22);
	overflow: hidden;
}

.thead {
	background: #151515;
	color: #fff;
	border-color: #070707;
	text-transform: uppercase;
	text-shadow: 1px 1px 0 #070707;
}

.thead a:link,
.thead a:visited,
.thead a:hover,
.thead a:active {
	color: #fff;
}

.tcat {
	background: #181818;
	color: #ccc;
	border-color: #101010 #101010 #262626;
}

.tcat a:link,
.tcat a:visited,
.tcat a:hover,
.tcat a:active {
	color: #fff;
}

.trow1,
.trow2 {
	background: #181818;
	color: #ccc;
	border-color: #101010 #101010 #262626;
}

.trow_shaded,
.trow_selected,
tr.trow_selected td {
	background: #1f1f1f;
	color: #fff;
}

table,
.smalltext,
.navigation {
	color: #ccc;
}

input.textbox,
textarea,
select {
	background: #0e0e0e;
	color: #ccc;
	border: 1px solid #3e3e3e;
}

input.button,
button,
.button {
	background: #262626;
	color: #fff;
	border: 1px solid #3e3e3e;
	border-radius: 3px;
}

#footer .upper {
	background: #151515;
	border-color: #262626;
}

#footer .lower {
	background: #0e0e0e;
	color: #969696;
}

#footer a:link,
#footer a:visited,
#footer a:hover,
#footer a:active {
	color: #ccc;
}

@media (max-width: 760px) {
	.wrapper {
		width: calc(100% - 20px);
	}

	#logo {
		min-height: 0;
	}

	#logo .wrapper {
		align-items: flex-start;
		flex-direction: column;
	}

	#logo img {
		max-width: 100%;
	}

	#logo ul.top_links {
		justify-content: flex-start;
	}
}
